import{_ as o,l as n,o as e,c as l,v as t,p as i,x as r,d as p,i as c,S as C}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"TPC-C / TPC-H","description":"","frontmatter":{"title":"TPC-C / TPC-H","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tpc-benchmarks.md","filePath":"cs/tpc-benchmarks.md","lastUpdated":1789023840000}'),d={name:"cs/tpc-benchmarks.md"};function h(T,a,P,_,m,f){const s=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="tpc-c-tpc-h" tabindex="-1">TPC-C / TPC-H <a class="header-anchor" href="#tpc-c-tpc-h" aria-label="Permalink to &quot;TPC-C / TPC-H&quot;">​</a></h1><div class="epigraph"><p>吞吐数字没有工作负载合同就不可比。TPC-C 钉 OLTP 新订单，TPC-H 钉决策支持的 22 条查询；审计规则比 QphH 数字更重要。</p><footer>—— TPC-C、TPC-H 规范；Gray 对基准的警告</footer></div><p><a href="/cs/exactly-once">上一课</a>谈流的效果语义。缺口是<strong>如何公平比系统</strong>：分析引擎与 OLTP 引擎不是同一条曲线。本课钉 TPC-C 与 TPC-H；Jepsen 下一课换正确性对抗。不把某厂商宣传数字当定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TPC-C：多仓、新订单、支付、交单、查询，有隔离与思考时间。tpmC 必须带性价比与审计。TPC-H：3NF schema、22 条、SF 规模因子，中间禁止改查询意图。缺口是读懂<strong>禁止事项</strong>（物化哪类、刷新规则），否则「更快」只是换了题。</p><p><span class="marginnote">TPC-DS、TPC-E 是后继形状，本课只钉 C 与 H 两条经典轴。列存对 H 极友好，对 C 的点更新不自动友好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跑基准：按规定装载、预热、测量窗口、报告。读别人的数字：SF、并行、是否允许物化视图、硬件。与星型/立方：H 的部分查询接近星型变换；C 是短事务+热点。与湖仓：H 可以跑在表格式上，但装载与刷新规则仍要声明。</p>',8)),(e(),i(C,null,{default:r(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22TPC-C%20%E4%BA%8B%E5%8A%A1%E6%B7%B7%E5%90%88%22%5D%20--%3E%20OLTP%5B%22%E9%9A%94%E7%A6%BB%20%2B%20%E7%83%AD%E7%82%B9%22%5D%0A%20%20H%5B%22TPC-H%2022%20%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20OLAP%5B%22%E6%89%AB%E6%8F%8F%20%2B%20%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>C 的瓶颈常是锁、日志、热点仓与组提交。H 的瓶颈常是 join 顺序、扫描、shuffle、统计。同一存储引擎很难两条都第一——这是 OLTP/OLAP 分叉，HTAP 用双路径而不是一份数字。列存对 H 极友好，对 C 的点更新不自动友好。计划回归在 H 的 22 条上极可见；缓冲 2Q 在 C 上抗扫描。</p><p>读报告：SF、节点数、是否允许物化、耐久档（fsync 是否开）、隔离级别。关 fsync 的 tpmC 与规范 D 不符。NewSQL 要用跨仓事务比例解释扩展，不是只报单仓。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教如何把基准改到刚好过审计的擦边球。下一课 Jepsen 测的是隔离谎言，不是 QphH。真实倾斜可能比规范生成器更狠，基准是合同不是生产副本。</p><p>后课默认：比性能先对齐基准与 D/隔离。无规范的自造基准常优化到演示查询。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>没有合同的吞吐不可比；先读 TPC 禁止项。</li><li>C 对事务热点，H 对分析计划。</li><li>Jepsen 下一课。</li><li>出处：TPC-C / TPC-H 规范；Gray 对测量。</li></ul>',8))])}const E=o(d,[["render",h]]);export{A as __pageData,E as default};
